done.script:
var pi = PhaseManager.current_phase_instance
if pi == null or not ("pending_assignments" in pi):
	return 0
var seen := {}
for a in pi.pending_assignments:
	seen[str(a.get("weapon_id", ""))] = true
return seen.size()

var sc = main.shooting_controller if "shooting_controller" in main else null
if sc == null or sc.weapon_tree == null:
	return false
var root = sc.weapon_tree.get_root()
if root == null:
	return false
var usable := 0
var child = root.get_first_child()
while child != null:
	if child.is_selectable(0):
		usable += 1
	child = child.get_next()
var pi = PhaseManager.current_phase_instance
if pi == null or not ("pending_assignments" in pi):
	return false
var seen := {}
for a in pi.pending_assignments:
	seen[str(a.get("weapon_id", ""))] = true
return usable > 0 and seen.size() >= usable
